app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const status = err.statusCode || err.status || 500;

  // Log full details server-side
  console.error(err);

  // Don’t leak internals
  const message = status >= 500 ? 'Internal server error' : (err.message || 'Request failed');

  res.status(status).json({ error: message });
});
```

### 2) Handle unhandled promise rejections / exceptions
These can crash the process or leave it in a bad state.
- Log and fail fast (often recommended in containerized environments) or at least log clearly.

```js
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Consider process.exit(1) with a supervisor (systemd/k8s) to restart cleanly
});
```

### 3) Don’t hardcode port; validate config
Hardcoding `3000` is fine for local dev, but for security/ops, prefer environment variables and validate them:

```js
const PORT = Number(process.env.PORT) || 3000;
if (!Number.isInteger(PORT) || PORT <= 0 || PORT > 65535) {
  throw new Error('Invalid PORT');
}
